window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-f8c3bcdd4209ea2f"]={"versions": [{"id": "FIG-f8c3bcdd4209ea2f", "releases": ["R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> AUTOSAR-Metamodell-Ausschnitt (UML-Klassendiagramm) der Adaptive Platform (<code>AUTOSAR_TPS_ManifestSpecification</code>).</li>\n<li><strong>Technischer Zweck:</strong> Modellierung des Mappings zwischen der deklarativen Diagnosekonfiguration (Diagnostic Management / <code>ara::diag</code>) und den Softwarekomponenten einer konkreten Applikation.</li>\n<li><strong>Funktionale Einordnung:</strong> Verknüpft die softwareunabhängige Definition der Service-Validierung (<code>DiagnosticServiceValidationInterface</code>) mit dem Prozesskontext (<code>ProcessDesign</code>) und dem konkreten Bereitstellungs-Port (<code>PPortPrototype</code>) innerhalb eines Executables. Dient dem Diagnostic Daemon als Konfigurationsgrundlage zur Laufzeitprüfung eingehender UDS-Service-Requests (Validierung von Session-, Sicherheits- oder Umgebungsbedingungen vor Serviceausführung).</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Metaklassen der Schnittstellenseite (Links)</p>\n<ul class=\"fig-list\">\n<li><strong><code>PortInterface</code></strong> (Spezialisierung von <code>ARElement</code>, <code>AtpBlueprint</code>, <code>AtpBlueprintable</code>, <code>AtpType</code>): Abstrakte Basisklasse aller AUTOSAR-Port-Schnittstellen.</li>\n<li><strong><code>DiagnosticPortInterface</code></strong>: Spezialisierte Schnittstellenklasse für Diagnosezwecke, abgeleitet von <code>PortInterface</code>.</li>\n<li><strong><code>DiagnosticServiceValidationInterface</code></strong>: Konkrete Spezifikation der Validierungsschnittstelle (abgeleitet von <code>DiagnosticPortInterface</code>). Definiert die Methoden/Signaturen, über die eine Applikation die Zulässigkeit diagnostischer Anfragen bestätigt oder ablehnt.</li>\n<li><strong><code>PPortPrototype</code></strong> (Spezialisierung von <code>AbstractProvidedPortPrototype</code>): Definiert den konkreten Bereitstellungs-Port (Provided Port) einer Software-Komponente.</li>\n<li>Stereotyp <code>«isOfType»</code>: Typisiert den Port über die Assoziation <code>+providedInterface</code> [0..1] <code>{redefines atpType}</code> gegen <code>PortInterface</code> (hier konkretisiert als <code>DiagnosticServiceValidationInterface</code>).</li>\n</ul>\n<p class=\"fig-p\">#### Metaklassen der Mapping- & Prozessseite (Rechts)</p>\n<ul class=\"fig-list\">\n<li><strong><code>Process</code></strong> (Spezialisierung von <code>AbstractExecutionContext</code>): Repräsentiert die OS-Prozessinstanz zur Laufzeit. Referenziert über <code>+design</code> [0..1] das zugehörige <code>ProcessDesign</code>.</li>\n<li><strong><code>ProcessDesign</code></strong> (<code>ARElement</code>): Deklarative Entwurfsdefinition des Prozesses vor dem finalen Deployment auf eine Machine.</li>\n<li><strong><code>DiagnosticSwMapping</code></strong> (abgeleitet von <code>DiagnosticMapping</code>): Basisklasse für Mappings von Diagnoseartefakten auf Software-Elemente.</li>\n<li><strong><code>DiagnosticServiceValidationMapping</code></strong> (abgeleitet von <code>DiagnosticSwMapping</code>): Zentrales Mapping-Element.</li>\n<li>Assoziation <code>+process</code> [0..1] mit Stereotyp <code>«atpSplitable»</code>: Verweist auf das <code>ProcessDesign</code>. Ermöglicht ARXML-Split (Aufteilung über mehrere Manifest-Dateien/Autorengrenzen hinweg).</li>\n<li>Zielgerichtete Abhängigkeit <code>+pPortPrototypeInExecutable</code> [0..1] mit Stereotypen <code>«instanceRef,atpUriDef»</code>: Definiert die URI-basierte Instanzreferenz auf den konkreten <code>PPortPrototype</code> im Kontext des Executables.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm selbst modelliert statische Manifest-Zusammenhänge; die daraus resultierende Laufzeitsequenz gestaltet sich wie folgt:</p>\n<ol class=\"fig-list\">\n<li><strong>Request-Eingang:</strong> Der <code>ara::diag</code>-Daemon empfängt eine UDS-Service-Anfrage (z. B. RoutineControl <code>$31</code>, WriteDataByIdentifier <code>$2E</code> oder DiagnosticSessionControl <code>$10</code>).</li>\n<li><strong>Validierungs-Lookup:</strong> Der Daemon ermittelt anhand des <code>DiagnosticServiceValidationMapping</code>, welcher Prozess (<code>Process</code>) und welcher Port (<code>PPortPrototype</code>) für die Validierung des angeforderten Services zuständig ist.</li>\n<li><strong>IPC-Call:</strong> Der Daemon ruft synchron oder asynchron über die generierten Service-Schnittstellen (<code>DiagnosticServiceValidationInterface</code>) die Validierungsmethode der Applikation auf.</li>\n<li><strong>Entscheidung & Rückmeldung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><em>Positiv:</em> Applikation bestätigt die Ausführbarkeit (<code>NRC 0x00</code> / Success) $\\rightarrow$ Service-Handler führt die eigentliche Diagnosefunktion aus.</li>\n<li><em>Negativ:</em> Applikation liefert einen Negative Response Code (NRC, z. B. <code>$22</code> <em>ConditionsNotCorrect</em> oder <code>$33</code> <em>SecurityAccessDenied</em>) $\\rightarrow$ Daemon bricht die Kette ab und sendet die NRC-Antwort direkt an den Diagnosetester.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Manifest-Generierung & ARXML-Splitting (RS_MANI_00005, RS_MANI_00061):</strong></li>\n<li>Durch <code>«atpSplitable»</code> an <code>+process</code> kann das Diagnose-Mapping in separaten Diagnose-Beschreibungsdateien gepflegt werden, unabhängig vom Prozess-Design-Manifest des Basis-Integrators.</li>\n<li><code>«instanceRef,atpUriDef»</code> erfordert eine lückenlose und konsistente Pfadangabe (<code>URI</code>) zur Auflösung des <code>PPortPrototype</code> über die Hierarchie <code>RootSwComponentPrototype</code> $\\rightarrow$ <code>SwComponentPrototype</code> $\\rightarrow$ <code>PPortPrototype</code> innerhalb des Ziel-<code>Executable</code>.</li>\n<li><strong>Applikations-Entwicklung (<code>ara::diag</code>):</strong></li>\n<li>Entwickler müssen eine Klasse implementieren, die von der aus dem <code>DiagnosticServiceValidationInterface</code> generierten Basisklasse erbt.</li>\n<li>Methoden müssen strikt echtzeit- und reentrant-fähig sein, da Verzögerungen bei der Validierung unmittelbar zu UDS-Timeout-Überschreitungen (P2/P2*-Timer) führen.</li>\n<li><strong>Konfigurations-Restriktionen:</strong></li>\n<li>Kardinalität <code>0..1</code>: Ist kein <code>DiagnosticServiceValidationMapping</code> für einen Dienst konfiguriert, führt der Daemon standardmäßig keine anwendungsspezifische Vorab-Validierung durch; die Validierungslogik verbleibt dann zwingend im regulären Service-Handler.</li>\n</ul>"}, {"id": "FIG-85a3d7db3b0d9f5f", "releases": ["R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> AUTOSAR-Metamodell-Ausschnitt (UML-Klassendiagramm) der Adaptive Platform (<code>AUTOSAR_TPS_ManifestSpecification</code>).</li>\n<li><strong>Technischer Zweck:</strong> Modellierung des Mappings zwischen der deklarativen Diagnosekonfiguration (Diagnostic Management / <code>ara::diag</code>) und den Softwarekomponenten einer konkreten Applikation.</li>\n<li><strong>Funktionale Einordnung:</strong> Verknüpft die softwareunabhängige Definition der Service-Validierung (<code>DiagnosticServiceValidationInterface</code>) mit dem Prozesskontext (<code>ProcessDesign</code>) und dem konkreten Bereitstellungs-Port (<code>PPortPrototype</code>) innerhalb eines Executables. Dient dem Diagnostic Daemon als Konfigurationsgrundlage zur Laufzeitprüfung eingehender UDS-Service-Requests (Validierung von Session-, Sicherheits- oder Umgebungsbedingungen vor Serviceausführung).</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Metaklassen der Schnittstellenseite (Links)</p>\n<ul class=\"fig-list\">\n<li><strong><code>PortInterface</code></strong> (Spezialisierung von <code>ARElement</code>, <code>AtpBlueprint</code>, <code>AtpBlueprintable</code>, <code>AtpType</code>): Abstrakte Basisklasse aller AUTOSAR-Port-Schnittstellen.</li>\n<li><strong><code>DiagnosticPortInterface</code></strong>: Spezialisierte Schnittstellenklasse für Diagnosezwecke, abgeleitet von <code>PortInterface</code>.</li>\n<li><strong><code>DiagnosticServiceValidationInterface</code></strong>: Konkrete Spezifikation der Validierungsschnittstelle (abgeleitet von <code>DiagnosticPortInterface</code>). Definiert die Methoden/Signaturen, über die eine Applikation die Zulässigkeit diagnostischer Anfragen bestätigt oder ablehnt.</li>\n<li><strong><code>PPortPrototype</code></strong> (Spezialisierung von <code>AbstractProvidedPortPrototype</code>): Definiert den konkreten Bereitstellungs-Port (Provided Port) einer Software-Komponente.</li>\n<li>Stereotyp <code>«isOfType»</code>: Typisiert den Port über die Assoziation <code>+providedInterface</code> [0..1] <code>{redefines atpType}</code> gegen <code>PortInterface</code> (hier konkretisiert als <code>DiagnosticServiceValidationInterface</code>).</li>\n</ul>\n<p class=\"fig-p\">#### Metaklassen der Mapping- & Prozessseite (Rechts)</p>\n<ul class=\"fig-list\">\n<li><strong><code>Process</code></strong> (Spezialisierung von <code>AbstractExecutionContext</code>): Repräsentiert die OS-Prozessinstanz zur Laufzeit. Referenziert über <code>+design</code> [0..1] das zugehörige <code>ProcessDesign</code>.</li>\n<li><strong><code>ProcessDesign</code></strong> (<code>ARElement</code>): Deklarative Entwurfsdefinition des Prozesses vor dem finalen Deployment auf eine Machine.</li>\n<li><strong><code>DiagnosticSwMapping</code></strong> (abgeleitet von <code>DiagnosticMapping</code>): Basisklasse für Mappings von Diagnoseartefakten auf Software-Elemente.</li>\n<li><strong><code>DiagnosticServiceValidationMapping</code></strong> (abgeleitet von <code>DiagnosticSwMapping</code>): Zentrales Mapping-Element.</li>\n<li>Assoziation <code>+process</code> [0..1] mit Stereotyp <code>«atpSplitable»</code>: Verweist auf das <code>ProcessDesign</code>. Ermöglicht ARXML-Split (Aufteilung über mehrere Manifest-Dateien/Autorengrenzen hinweg).</li>\n<li>Zielgerichtete Abhängigkeit <code>+pPortPrototypeInExecutable</code> [0..1] mit Stereotypen <code>«instanceRef,atpUriDef»</code>: Definiert die URI-basierte Instanzreferenz auf den konkreten <code>PPortPrototype</code> im Kontext des Executables.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm selbst modelliert statische Manifest-Zusammenhänge; die daraus resultierende Laufzeitsequenz gestaltet sich wie folgt:</p>\n<ol class=\"fig-list\">\n<li><strong>Request-Eingang:</strong> Der <code>ara::diag</code>-Daemon empfängt eine UDS-Service-Anfrage (z. B. RoutineControl <code>$31</code>, WriteDataByIdentifier <code>$2E</code> oder DiagnosticSessionControl <code>$10</code>).</li>\n<li><strong>Validierungs-Lookup:</strong> Der Daemon ermittelt anhand des <code>DiagnosticServiceValidationMapping</code>, welcher Prozess (<code>Process</code>) und welcher Port (<code>PPortPrototype</code>) für die Validierung des angeforderten Services zuständig ist.</li>\n<li><strong>IPC-Call:</strong> Der Daemon ruft synchron oder asynchron über die generierten Service-Schnittstellen (<code>DiagnosticServiceValidationInterface</code>) die Validierungsmethode der Applikation auf.</li>\n<li><strong>Entscheidung & Rückmeldung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><em>Positiv:</em> Applikation bestätigt die Ausführbarkeit (<code>NRC 0x00</code> / Success) $\\rightarrow$ Service-Handler führt die eigentliche Diagnosefunktion aus.</li>\n<li><em>Negativ:</em> Applikation liefert einen Negative Response Code (NRC, z. B. <code>$22</code> <em>ConditionsNotCorrect</em> oder <code>$33</code> <em>SecurityAccessDenied</em>) $\\rightarrow$ Daemon bricht die Kette ab und sendet die NRC-Antwort direkt an den Diagnosetester.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Manifest-Generierung & ARXML-Splitting (RS_MANI_00005, RS_MANI_00061):</strong></li>\n<li>Durch <code>«atpSplitable»</code> an <code>+process</code> kann das Diagnose-Mapping in separaten Diagnose-Beschreibungsdateien gepflegt werden, unabhängig vom Prozess-Design-Manifest des Basis-Integrators.</li>\n<li><code>«instanceRef,atpUriDef»</code> erfordert eine lückenlose und konsistente Pfadangabe (<code>URI</code>) zur Auflösung des <code>PPortPrototype</code> über die Hierarchie <code>RootSwComponentPrototype</code> $\\rightarrow$ <code>SwComponentPrototype</code> $\\rightarrow$ <code>PPortPrototype</code> innerhalb des Ziel-<code>Executable</code>.</li>\n<li><strong>Applikations-Entwicklung (<code>ara::diag</code>):</strong></li>\n<li>Entwickler müssen eine Klasse implementieren, die von der aus dem <code>DiagnosticServiceValidationInterface</code> generierten Basisklasse erbt.</li>\n<li>Methoden müssen strikt echtzeit- und reentrant-fähig sein, da Verzögerungen bei der Validierung unmittelbar zu UDS-Timeout-Überschreitungen (P2/P2*-Timer) führen.</li>\n<li><strong>Konfigurations-Restriktionen:</strong></li>\n<li>Kardinalität <code>0..1</code>: Ist kein <code>DiagnosticServiceValidationMapping</code> für einen Dienst konfiguriert, führt der Daemon standardmäßig keine anwendungsspezifische Vorab-Validierung durch; die Validierungslogik verbleibt dann zwingend im regulären Service-Handler.</li>\n</ul>"}, {"id": "FIG-e6cbe5d9d1b74c8f", "releases": ["R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> AUTOSAR-Metamodell-Ausschnitt (UML-Klassendiagramm) der Adaptive Platform (<code>AUTOSAR_TPS_ManifestSpecification</code>).</li>\n<li><strong>Technischer Zweck:</strong> Modellierung des Mappings zwischen der deklarativen Diagnosekonfiguration (Diagnostic Management / <code>ara::diag</code>) und den Softwarekomponenten einer konkreten Applikation.</li>\n<li><strong>Funktionale Einordnung:</strong> Verknüpft die softwareunabhängige Definition der Service-Validierung (<code>DiagnosticServiceValidationInterface</code>) mit dem Prozesskontext (<code>ProcessDesign</code>) und dem konkreten Bereitstellungs-Port (<code>PPortPrototype</code>) innerhalb eines Executables. Dient dem Diagnostic Daemon als Konfigurationsgrundlage zur Laufzeitprüfung eingehender UDS-Service-Requests (Validierung von Session-, Sicherheits- oder Umgebungsbedingungen vor Serviceausführung).</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Metaklassen der Schnittstellenseite (Links)</p>\n<ul class=\"fig-list\">\n<li><strong><code>PortInterface</code></strong> (Spezialisierung von <code>ARElement</code>, <code>AtpBlueprint</code>, <code>AtpBlueprintable</code>, <code>AtpType</code>): Abstrakte Basisklasse aller AUTOSAR-Port-Schnittstellen.</li>\n<li><strong><code>DiagnosticPortInterface</code></strong>: Spezialisierte Schnittstellenklasse für Diagnosezwecke, abgeleitet von <code>PortInterface</code>.</li>\n<li><strong><code>DiagnosticServiceValidationInterface</code></strong>: Konkrete Spezifikation der Validierungsschnittstelle (abgeleitet von <code>DiagnosticPortInterface</code>). Definiert die Methoden/Signaturen, über die eine Applikation die Zulässigkeit diagnostischer Anfragen bestätigt oder ablehnt.</li>\n<li><strong><code>PPortPrototype</code></strong> (Spezialisierung von <code>AbstractProvidedPortPrototype</code>): Definiert den konkreten Bereitstellungs-Port (Provided Port) einer Software-Komponente.</li>\n<li>Stereotyp <code>«isOfType»</code>: Typisiert den Port über die Assoziation <code>+providedInterface</code> [0..1] <code>{redefines atpType}</code> gegen <code>PortInterface</code> (hier konkretisiert als <code>DiagnosticServiceValidationInterface</code>).</li>\n</ul>\n<p class=\"fig-p\">#### Metaklassen der Mapping- & Prozessseite (Rechts)</p>\n<ul class=\"fig-list\">\n<li><strong><code>Process</code></strong> (Spezialisierung von <code>AbstractExecutionContext</code>): Repräsentiert die OS-Prozessinstanz zur Laufzeit. Referenziert über <code>+design</code> [0..1] das zugehörige <code>ProcessDesign</code>.</li>\n<li><strong><code>ProcessDesign</code></strong> (<code>ARElement</code>): Deklarative Entwurfsdefinition des Prozesses vor dem finalen Deployment auf eine Machine.</li>\n<li><strong><code>DiagnosticSwMapping</code></strong> (abgeleitet von <code>DiagnosticMapping</code>): Basisklasse für Mappings von Diagnoseartefakten auf Software-Elemente.</li>\n<li><strong><code>DiagnosticServiceValidationMapping</code></strong> (abgeleitet von <code>DiagnosticSwMapping</code>): Zentrales Mapping-Element.</li>\n<li>Assoziation <code>+process</code> [0..1] mit Stereotyp <code>«atpSplitable»</code>: Verweist auf das <code>ProcessDesign</code>. Ermöglicht ARXML-Split (Aufteilung über mehrere Manifest-Dateien/Autorengrenzen hinweg).</li>\n<li>Zielgerichtete Abhängigkeit <code>+pPortPrototypeInExecutable</code> [0..1] mit Stereotypen <code>«instanceRef,atpUriDef»</code>: Definiert die URI-basierte Instanzreferenz auf den konkreten <code>PPortPrototype</code> im Kontext des Executables.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm selbst modelliert statische Manifest-Zusammenhänge; die daraus resultierende Laufzeitsequenz gestaltet sich wie folgt:</p>\n<ol class=\"fig-list\">\n<li><strong>Request-Eingang:</strong> Der <code>ara::diag</code>-Daemon empfängt eine UDS-Service-Anfrage (z. B. RoutineControl <code>$31</code>, WriteDataByIdentifier <code>$2E</code> oder DiagnosticSessionControl <code>$10</code>).</li>\n<li><strong>Validierungs-Lookup:</strong> Der Daemon ermittelt anhand des <code>DiagnosticServiceValidationMapping</code>, welcher Prozess (<code>Process</code>) und welcher Port (<code>PPortPrototype</code>) für die Validierung des angeforderten Services zuständig ist.</li>\n<li><strong>IPC-Call:</strong> Der Daemon ruft synchron oder asynchron über die generierten Service-Schnittstellen (<code>DiagnosticServiceValidationInterface</code>) die Validierungsmethode der Applikation auf.</li>\n<li><strong>Entscheidung & Rückmeldung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><em>Positiv:</em> Applikation bestätigt die Ausführbarkeit (<code>NRC 0x00</code> / Success) $\\rightarrow$ Service-Handler führt die eigentliche Diagnosefunktion aus.</li>\n<li><em>Negativ:</em> Applikation liefert einen Negative Response Code (NRC, z. B. <code>$22</code> <em>ConditionsNotCorrect</em> oder <code>$33</code> <em>SecurityAccessDenied</em>) $\\rightarrow$ Daemon bricht die Kette ab und sendet die NRC-Antwort direkt an den Diagnosetester.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Manifest-Generierung & ARXML-Splitting (RS_MANI_00005, RS_MANI_00061):</strong></li>\n<li>Durch <code>«atpSplitable»</code> an <code>+process</code> kann das Diagnose-Mapping in separaten Diagnose-Beschreibungsdateien gepflegt werden, unabhängig vom Prozess-Design-Manifest des Basis-Integrators.</li>\n<li><code>«instanceRef,atpUriDef»</code> erfordert eine lückenlose und konsistente Pfadangabe (<code>URI</code>) zur Auflösung des <code>PPortPrototype</code> über die Hierarchie <code>RootSwComponentPrototype</code> $\\rightarrow$ <code>SwComponentPrototype</code> $\\rightarrow$ <code>PPortPrototype</code> innerhalb des Ziel-<code>Executable</code>.</li>\n<li><strong>Applikations-Entwicklung (<code>ara::diag</code>):</strong></li>\n<li>Entwickler müssen eine Klasse implementieren, die von der aus dem <code>DiagnosticServiceValidationInterface</code> generierten Basisklasse erbt.</li>\n<li>Methoden müssen strikt echtzeit- und reentrant-fähig sein, da Verzögerungen bei der Validierung unmittelbar zu UDS-Timeout-Überschreitungen (P2/P2*-Timer) führen.</li>\n<li><strong>Konfigurations-Restriktionen:</strong></li>\n<li>Kardinalität <code>0..1</code>: Ist kein <code>DiagnosticServiceValidationMapping</code> für einen Dienst konfiguriert, führt der Daemon standardmäßig keine anwendungsspezifische Vorab-Validierung durch; die Validierungslogik verbleibt dann zwingend im regulären Service-Handler.</li>\n</ul>"}, {"id": "FIG-60c5bc97828a2796", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> AUTOSAR-Metamodell-Ausschnitt (UML-Klassendiagramm) der Adaptive Platform (<code>AUTOSAR_TPS_ManifestSpecification</code>).</li>\n<li><strong>Technischer Zweck:</strong> Modellierung des Mappings zwischen der deklarativen Diagnosekonfiguration (Diagnostic Management / <code>ara::diag</code>) und den Softwarekomponenten einer konkreten Applikation.</li>\n<li><strong>Funktionale Einordnung:</strong> Verknüpft die softwareunabhängige Definition der Service-Validierung (<code>DiagnosticServiceValidationInterface</code>) mit dem Prozesskontext (<code>ProcessDesign</code>) und dem konkreten Bereitstellungs-Port (<code>PPortPrototype</code>) innerhalb eines Executables. Dient dem Diagnostic Daemon als Konfigurationsgrundlage zur Laufzeitprüfung eingehender UDS-Service-Requests (Validierung von Session-, Sicherheits- oder Umgebungsbedingungen vor Serviceausführung).</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Metaklassen der Schnittstellenseite (Links)</p>\n<ul class=\"fig-list\">\n<li><strong><code>PortInterface</code></strong> (Spezialisierung von <code>ARElement</code>, <code>AtpBlueprint</code>, <code>AtpBlueprintable</code>, <code>AtpType</code>): Abstrakte Basisklasse aller AUTOSAR-Port-Schnittstellen.</li>\n<li><strong><code>DiagnosticPortInterface</code></strong>: Spezialisierte Schnittstellenklasse für Diagnosezwecke, abgeleitet von <code>PortInterface</code>.</li>\n<li><strong><code>DiagnosticServiceValidationInterface</code></strong>: Konkrete Spezifikation der Validierungsschnittstelle (abgeleitet von <code>DiagnosticPortInterface</code>). Definiert die Methoden/Signaturen, über die eine Applikation die Zulässigkeit diagnostischer Anfragen bestätigt oder ablehnt.</li>\n<li><strong><code>PPortPrototype</code></strong> (Spezialisierung von <code>AbstractProvidedPortPrototype</code>): Definiert den konkreten Bereitstellungs-Port (Provided Port) einer Software-Komponente.</li>\n<li>Stereotyp <code>«isOfType»</code>: Typisiert den Port über die Assoziation <code>+providedInterface</code> [0..1] <code>{redefines atpType}</code> gegen <code>PortInterface</code> (hier konkretisiert als <code>DiagnosticServiceValidationInterface</code>).</li>\n</ul>\n<p class=\"fig-p\">#### Metaklassen der Mapping- & Prozessseite (Rechts)</p>\n<ul class=\"fig-list\">\n<li><strong><code>Process</code></strong> (Spezialisierung von <code>AbstractExecutionContext</code>): Repräsentiert die OS-Prozessinstanz zur Laufzeit. Referenziert über <code>+design</code> [0..1] das zugehörige <code>ProcessDesign</code>.</li>\n<li><strong><code>ProcessDesign</code></strong> (<code>ARElement</code>): Deklarative Entwurfsdefinition des Prozesses vor dem finalen Deployment auf eine Machine.</li>\n<li><strong><code>DiagnosticSwMapping</code></strong> (abgeleitet von <code>DiagnosticMapping</code>): Basisklasse für Mappings von Diagnoseartefakten auf Software-Elemente.</li>\n<li><strong><code>DiagnosticServiceValidationMapping</code></strong> (abgeleitet von <code>DiagnosticSwMapping</code>): Zentrales Mapping-Element.</li>\n<li>Assoziation <code>+process</code> [0..1] mit Stereotyp <code>«atpSplitable»</code>: Verweist auf das <code>ProcessDesign</code>. Ermöglicht ARXML-Split (Aufteilung über mehrere Manifest-Dateien/Autorengrenzen hinweg).</li>\n<li>Zielgerichtete Abhängigkeit <code>+pPortPrototypeInExecutable</code> [0..1] mit Stereotypen <code>«instanceRef,atpUriDef»</code>: Definiert die URI-basierte Instanzreferenz auf den konkreten <code>PPortPrototype</code> im Kontext des Executables.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm selbst modelliert statische Manifest-Zusammenhänge; die daraus resultierende Laufzeitsequenz gestaltet sich wie folgt:</p>\n<ol class=\"fig-list\">\n<li><strong>Request-Eingang:</strong> Der <code>ara::diag</code>-Daemon empfängt eine UDS-Service-Anfrage (z. B. RoutineControl <code>$31</code>, WriteDataByIdentifier <code>$2E</code> oder DiagnosticSessionControl <code>$10</code>).</li>\n<li><strong>Validierungs-Lookup:</strong> Der Daemon ermittelt anhand des <code>DiagnosticServiceValidationMapping</code>, welcher Prozess (<code>Process</code>) und welcher Port (<code>PPortPrototype</code>) für die Validierung des angeforderten Services zuständig ist.</li>\n<li><strong>IPC-Call:</strong> Der Daemon ruft synchron oder asynchron über die generierten Service-Schnittstellen (<code>DiagnosticServiceValidationInterface</code>) die Validierungsmethode der Applikation auf.</li>\n<li><strong>Entscheidung & Rückmeldung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li><em>Positiv:</em> Applikation bestätigt die Ausführbarkeit (<code>NRC 0x00</code> / Success) $\\rightarrow$ Service-Handler führt die eigentliche Diagnosefunktion aus.</li>\n<li><em>Negativ:</em> Applikation liefert einen Negative Response Code (NRC, z. B. <code>$22</code> <em>ConditionsNotCorrect</em> oder <code>$33</code> <em>SecurityAccessDenied</em>) $\\rightarrow$ Daemon bricht die Kette ab und sendet die NRC-Antwort direkt an den Diagnosetester.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Manifest-Generierung & ARXML-Splitting (RS_MANI_00005, RS_MANI_00061):</strong></li>\n<li>Durch <code>«atpSplitable»</code> an <code>+process</code> kann das Diagnose-Mapping in separaten Diagnose-Beschreibungsdateien gepflegt werden, unabhängig vom Prozess-Design-Manifest des Basis-Integrators.</li>\n<li><code>«instanceRef,atpUriDef»</code> erfordert eine lückenlose und konsistente Pfadangabe (<code>URI</code>) zur Auflösung des <code>PPortPrototype</code> über die Hierarchie <code>RootSwComponentPrototype</code> $\\rightarrow$ <code>SwComponentPrototype</code> $\\rightarrow$ <code>PPortPrototype</code> innerhalb des Ziel-<code>Executable</code>.</li>\n<li><strong>Applikations-Entwicklung (<code>ara::diag</code>):</strong></li>\n<li>Entwickler müssen eine Klasse implementieren, die von der aus dem <code>DiagnosticServiceValidationInterface</code> generierten Basisklasse erbt.</li>\n<li>Methoden müssen strikt echtzeit- und reentrant-fähig sein, da Verzögerungen bei der Validierung unmittelbar zu UDS-Timeout-Überschreitungen (P2/P2*-Timer) führen.</li>\n<li><strong>Konfigurations-Restriktionen:</strong></li>\n<li>Kardinalität <code>0..1</code>: Ist kein <code>DiagnosticServiceValidationMapping</code> für einen Dienst konfiguriert, führt der Daemon standardmäßig keine anwendungsspezifische Vorab-Validierung durch; die Validierungslogik verbleibt dann zwingend im regulären Service-Handler.</li>\n</ul>"}], "trans": [{"from": "FIG-f8c3bcdd4209ea2f", "to": "FIG-85a3d7db3b0d9f5f", "fr": "R22-11", "tr": "R23-11", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li><code>DiagnosticPortInterface</code>: Neu positioniert rechts neben <code>PortInterface</code> (Generalisierungspfeil verläuft nun horizontal nach links statt vertikal nach oben).</li>\n<li><code>Process</code>: Neu positioniert links neben <code>ProcessDesign</code> (Assoziationspfeil <code>+design</code> verläuft nun horizontal nach rechts statt vertikal nach unten).</li>\n<li><code>DiagnosticServiceValidationMapping</code>: Horizontal verbreitert und neu ausgerichtet, um die neu platzierten Metaklassen zu unterspannen.</li>\n</ul>"}, {"from": "FIG-85a3d7db3b0d9f5f", "to": "FIG-e6cbe5d9d1b74c8f", "fr": "R23-11", "tr": "R24-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-e6cbe5d9d1b74c8f", "to": "FIG-60c5bc97828a2796", "fr": "R24-11", "tr": "R25-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
